import java.util.*;

public class Main {
    int superPow(int a, int[] b) {
        // WARNING: only works for illustration when b is small; the real
        // constraint gives b as up to 2000 digits, far too large to ever loop over
        long bValue = 0;
        for (int digit : b) {
            bValue = bValue * 10 + digit;         // this overflows long for a large b
        }
        long result = 1;
        for (long i = 0; i < bValue; i++) {
            result = (result * a) % 1337;           // multiply and immediately reduce mod 1337
        }
        return (int) result;
    }

    public static void main(String[] args) {
        int a = 2;
        int[] b = {1, 0};
        Main solution = new Main();
        System.out.println(solution.superPow(a, b));
    }
}

