import java.util.*;

public class Main {
    long modPow(long base, long exp, long mod) {
        base %= mod;
        long result = 1;
        while (exp > 0) {
            if (exp % 2 == 1) {
                result = (result * base) % mod;    // fold in this power of the base when the bit is set
            }
            base = (base * base) % mod;              // square the base for the next bit
            exp /= 2;
        }
        return result;
    }

    int superPow(int a, int[] b) {
        long aa = a % 1337;
        long result = 1;
        for (int digit : b) {                        // walk through b's digits, most significant first
            result = modPow(result, 10, 1337) * modPow(aa, digit, 1337) % 1337;  // combine via fast power
        }
        return (int) result;
    }

    public static void main(String[] args) {
        int a = 2;
        int[] b = {1, 0};
        Main solution = new Main();
        System.out.println(solution.superPow(a, b));
    }
}

